using System.Collections;
using UnityEngine;
using UnityEngine.Localization.SmartFormat;

namespace Astrea;

[CreateAssetMenu(fileName = "OnAstriumActivateOrbEffect", menuName = "Data/Battle/Effects/Orion/OnAstriumActivateOrb Effect")]
public class OnAstriumActivateOrbEffect : Effect
{
	[Header("Astrium Activate")]
	[SerializeField]
	private StarAbility starAbility;

	[SerializeField]
	private CurrentCorruptedAnimals currentCorruptedAnimals;

	[SerializeField]
	private AstriumEffect astriumEffect;

	public override string GetEffectDescription(int amount, GameObject effectOwner = null)
	{
		string text = "";
		text = Smart.Format(base.localizationManager.GetLocalizedCastOrbActionBase(), starAbility.StarAbilityID.GetSpriteText() + starAbility.GetLocalizedNameWithoutModifiers());
		return Smart.Format(base.localizationManager.GetLocalizedWhenTriggered(), astriumEffect.GetEffectName(), base.localizationManager.GetLocalizedXTimesFormatted(text, amount)) + AppendedDescription();
	}

	public override int ActivateEffect(int effectAmount, GameObject effectOwner)
	{
		ReferenceSingleton<GameStateManager>.Instance.ActionsQueueState.EnqueueAction(ActivateStarAbility(effectAmount));
		ReferenceSingleton<GameStateManager>.Instance.SetState(ReferenceSingleton<GameStateManager>.Instance.ActionsQueueState);
		return effectAmount;
	}

	private IEnumerator ActivateStarAbility(int activationAmount)
	{
		for (int i = 0; i < activationAmount; i++)
		{
			starAbility.OnActivateStarAbility();
			yield return new WaitForSeconds(0.4f);
			if (!currentCorruptedAnimals.IsAnyEnemyActive())
			{
				break;
			}
		}
	}
}
